import 'package:freezed_annotation/freezed_annotation.dart';

import '../../domain/entities/product.dart';
import '../../domain/entities/product_sort.dart';

part 'product_list_state.freezed.dart';

/// Immutable state for product discovery (PRES-02): items + pagination +
/// active filters; ==/copyWith generated by freezed.
@freezed
abstract class ProductListState with _$ProductListState {
  const factory ProductListState({
    @Default([]) List<Product> items,
    @Default(true) bool hasMore,
    @Default(false) bool isLoadingMore,
    String? query,
    String? categoryId,
    @Default(ProductSort.newest) ProductSort sort,
  }) = _ProductListState;

  static ProductListState initial({
    String? query,
    String? categoryId,
    ProductSort sort = ProductSort.newest,
  }) {
    return ProductListState(
      query: query,
      categoryId: categoryId,
      sort: sort,
    );
  }
}
